import styled from "styled-components";

const Card = styled.div`
  width: 100%;
  background: #ffffff;
  border-radius: 24px;
  box-shadow: 0 24px 60px rgba(15, 23, 42, 0.12);
  padding: 32px;
  box-sizing: border-box;
`;

export default Card;
